1	export type Item = {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	};
7	
8	export type Damage = { itemType: string; amount: number };
9	
10	export type Incident = { cause: string; damages: Damage[] };
11	
12	export type QuoteStep = { op: "quote"; items: Item[] };
13	
14	// `policy` is the zero-based index of the quote step that created the policy.
15	export type ClaimStep = { op: "claim"; policy: number; incident: Incident };
16	
17	export type Step = QuoteStep | ClaimStep;
18	
19	export type Customer = { yearsWithMHPCO: number };
20	
21	export type Scenario = {
22	  customer: Customer;
23	  steps: Step[];
24	};
25	
26	export type QuoteResult = { premium: number };
27	
28	export type ClaimResult = { payout: number; remainingCap: number };
29	
30	export type StepResult = QuoteResult | ClaimResult;
31	
32	export type ScenarioResult = { results: StepResult[] };
33	
34	const BASE_PRICE_BY_TYPE: Record<string, number> = {
35	  sword: 100,
36	  amulet: 60,
37	  staff: 80,
38	  potion: 40,
39	  rune: 25,
40	  moonstone: 25,
41	};
42	
43	// What an item is insured for, as opposed to what it costs to insure.
44	const INSURANCE_VALUE_BY_TYPE: Record<string, number> = {
45	  sword: 1000,
46	  amulet: 600,
47	  staff: 800,
48	  potion: 400,
49	  rune: 250,
50	  moonstone: 250,
51	};
52	
53	const FIRST_INSURANCE_MULTIPLIER = 1.1;
54	const CONTRACT_FEE = 5;
55	
56	const BUILDING_BLOCK_SIZE = 3;
57	const BUILDING_BLOCK_PRICE = 60;
58	
59	const CURSED_SURCHARGE_RATE = 0.5;
60	const HIGH_ENCHANTMENT_LEVEL = 5;
61	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
62	
63	// Each surcharge adds a percentage of the base price when its condition holds.
64	// Rates add together, so a cursed and highly enchanted item pays 1 + 0.5 + 0.3.
65	const RISK_SURCHARGES: { appliesTo: (item: Item) => boolean; rate: number }[] = [
66	  { appliesTo: (item) => item.cursed === true, rate: CURSED_SURCHARGE_RATE },
67	  {
68	    appliesTo: (item) => (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL,
69	    rate: HIGH_ENCHANTMENT_SURCHARGE_RATE,
70	  },
71	];
72	
73	const totalSurchargeRateFor = (item: Item): number =>
74	  RISK_SURCHARGES.filter((surcharge) => surcharge.appliesTo(item)).reduce(
75	    (total, surcharge) => total + surcharge.rate,
76	    0,
77	  );
78	
79	// Risk surcharges apply per item, before the contract-level multiplier and fee.
80	const riskAdjustedPriceOfItem = (item: Item): number =>
81	  BASE_PRICE_BY_TYPE[item.type] * (1 + totalSurchargeRateFor(item));
82	
83	const sumOfIndividualPrices = (items: Item[]): number =>
84	  items.reduce((total, item) => total + riskAdjustedPriceOfItem(item), 0);
85	
86	// "Alike" in the price list means same type — material and enchantment do not
87	// affect whether components group into a building block.
88	const groupByType = (items: Item[]): Item[][] => [
89	  ...items
90	    .reduce(
91	      (groups, item) =>
92	        groups.set(item.type, [...(groups.get(item.type) ?? []), item]),
93	      new Map<string, Item[]>(),
94	    )
95	    .values(),
96	];
97	
98	// Every three alike components form a building block priced at 60 G; the
99	// remainder of the group is priced individually.
100	const priceOfAlikeGroup = (group: Item[]): number => {
101	  const blocks = Math.floor(group.length / BUILDING_BLOCK_SIZE);
102	  const leftovers = group.slice(blocks * BUILDING_BLOCK_SIZE);
103	
104	  return blocks * BUILDING_BLOCK_PRICE + sumOfIndividualPrices(leftovers);
105	};
106	
107	// The insured value of the whole list: price-list figures plus per-item risk
108	// surcharges, before any contract-level multiplier or fee.
109	const insuredValueOf = (items: Item[]): number =>
110	  groupByType(items).reduce((total, group) => total + priceOfAlikeGroup(group), 0);
111	
112	const LOYALTY_YEARS = 2;
113	const LOYALTY_DISCOUNT_RATE = 0.2;
114	
115	const loyaltyMultiplierFor = (customer: Customer): number =>
116	  customer.yearsWithMHPCO >= LOYALTY_YEARS ? 1 - LOYALTY_DISCOUNT_RATE : 1;
117	
118	const REPEAT_CONTRACT_DISCOUNT_RATE = 0.15;
119	
120	// A first insurance carries an assessment surcharge; every later contract
121	// earns the repeat-customer discount instead.
122	const repeatCustomerMultiplierFor = (precedingContracts: number): number =>
123	  precedingContracts === 0
124	    ? FIRST_INSURANCE_MULTIPLIER
125	    : 1 - REPEAT_CONTRACT_DISCOUNT_RATE;
126	
127	// Customer-dependent factors that scale the whole contract, as opposed to the
128	// per-item risk surcharges already folded into the insured value.
129	const contractMultiplierFor = (
130	  customer: Customer,
131	  precedingContracts: number,
132	): number =>
133	  loyaltyMultiplierFor(customer) * repeatCustomerMultiplierFor(precedingContracts);
134	
135	// Amounts are rounded up, in MHPCO's favor. The product is first snapped to
136	// six decimals so IEEE754 noise (100 × 1.1 = 110.00000000000001) does not
137	// push an exact amount to the next whole G.
138	const roundedUpInMHPCOsFavor = (amount: number): number =>
139	  Math.ceil(Number(amount.toFixed(6)));
140	
141	const quoteStep = (
142	  step: QuoteStep,
143	  customer: Customer,
144	  precedingContracts: number,
145	): QuoteResult => ({
146	  premium:
147	    roundedUpInMHPCOsFavor(
148	      insuredValueOf(step.items) *
149	        contractMultiplierFor(customer, precedingContracts),
150	    ) + CONTRACT_FEE,
151	});
152	
153	const DEDUCTIBLE = 100;
154	const CAP_FACTOR = 2;
155	
156	const insuranceSumOf = (items: Item[]): number =>
157	  items.reduce((total, item) => total + INSURANCE_VALUE_BY_TYPE[item.type], 0);
158	
159	const claimStep = (step: ClaimStep, steps: Step[]): ClaimResult => {
160	  const policy = steps[step.policy] as QuoteStep;
161	  const cap = CAP_FACTOR * insuranceSumOf(policy.items);
162	  const damage = step.incident.damages.reduce(
163	    (total, { amount }) => total + amount,
164	    0,
165	  );
166	  const payout = damage - DEDUCTIBLE;
167	
168	  return { payout, remainingCap: cap - payout };
169	};
170	
171	export const runScenario = (scenario: Scenario): ScenarioResult => ({
172	  results: scenario.steps.map((step, index) =>
173	    step.op === "quote"
174	      ? quoteStep(step, scenario.customer, index)
175	      : claimStep(step, scenario.steps),
176	  ),
177	});
